  SASS, que não está disponível no Pyodide/Shinylive). */
  --bs-primary: #0047ab;
  --bs-primary-rgb: 0, 71, 171;
  --bs-link-color: #0047ab;
  --bs-link-color-rgb: 0, 71, 171;
  --bs-link-hover-color: #003580;
}

.btn-primary {
  --bs-btn-bg: #0047ab;
  --bs-btn-border-color: #0047ab;
  --bs-btn-hover-bg: #003580;
  --bs-btn-hover-border-color: #003580;
  --bs-btn-active-bg: #003580;
  --bs-btn-active-border-color: #003580;
