.nav-underline .nav-link.active {
  color: #0047ab !important;
  border-bottom-color: #0047ab !important;
}

a {
  color: #0047ab;
}

body {
  background: #f5f6f8;
}

.navbar-brand {
  font-weight: 800 !important;
  font-size: 1.7rem !important;
  color: var(--cor-marca) !important;
}

.tab-content {
  padding-top: 1rem;
}

/* Cards de KPI */
.grade-cards {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.card,
.card-kpi {
  min-width: 0;
  border-radius: 8px;
  box-shadow: var(--sombra-card);
  margin-bottom: 0 !important;
}

.card-kpi .fa {
  height: 1.6em;
  width: 1.6em;
  opacity: 0.85;
}

.card .valor,
.card-kpi .valor {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.2;
}

.card .titulo,
.card-kpi .titulo {
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  opacity: 0.9;
}

.linha-card-grafico {
  display: grid;
  grid-template-columns: 1fr 3fr;
  gap: 1rem;
  margin-bottom: 1.25rem;
  align-items: stretch;
}

.linha-cartoes {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
  margin-bottom: 1.25rem;
}

.grade-graficos {
