.grafico-card,
.mapa-card {
  min-width: 0;
  background: var(--cor-fundo-card);
  border-radius: 8px;
  box-shadow: var(--sombra-card);
  padding: 0.75rem;
  margin-bottom: 1rem;
}

.mapa-card {
  padding: 0.5rem;
}

/* Filtros */
.filtros {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: flex-end;
  background: var(--cor-fundo-card);
  border-radius: 8px;
  box-shadow: var(--sombra-card);
  padding: 0.9rem 1.1rem;
  margin-bottom: 1rem;
}

.filtros .form-group,
.filtros .shiny-input-container {
  margin-bottom: 0 !important;
  min-width: 220px;
}

/* Tabelas + exportação */
.tabela-card {
  background: var(--cor-fundo-card);
  border-radius: 8px;
  box-shadow: var(--sombra-card);
