  font-size: 1.35rem;
  font-weight: 700;
  color: var(--cor-marca);
}

.acao-card ul.lista-simples {
  margin: 0;
  padding-left: 1.1rem;
  max-height: 160px;
  overflow-y: auto;
  font-size: 0.92rem;
  line-height: 1.6;
  text-align: left;
}

/* Despesa por Órgão: listas-cartão */
.lista-cartao {
  min-width: 0;
  background: var(--cor-fundo-card);
  border-radius: 8px;
  box-shadow: var(--sombra-card);
  padding: 0.9rem 1.1rem;
  display: flex;
  flex-direction: column;
}

.lista-cartao-titulo {
  margin: 0 0 0.5rem;
  font-size: 0.95rem;
}

.lista-cartao-corpo {
  overflow-y: auto;
  max-height: 320px;
}

.lista-cartao-item {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.75rem;
  padding: 0.5rem 0;
  border-top: 1px solid var(--cor-divisor-suave);
}

.lista-cartao-item:first-child {
  border-top: none;
}

.lista-cartao-item .valor {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--cor-marca);
  white-space: nowrap;
}

/* Sobre o Painel */
.grade-blocos {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 20px;
}

.bloco {
  min-width: 0;
  background: var(--cor-fundo-card);
  border-radius: 8px;
  box-shadow: var(--sombra-card);
  padding: 1.1rem 1.25rem;
}

.bloco h5 {
  margin: 0 0 8px;
  color: var(--cor-marca);
}

.bloco p {
  margin: 0;
  font-size: 0.88rem;
  color: var(--cor-texto-suave);
}

/* Links Úteis */
.grade-links {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.link-card {
  min-width: 0;
  background: var(--cor-fundo-card);
  border-radius: 8px;
  box-shadow: var(--sombra-card);
  padding: 1.1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.link-card h5 {
  margin: 0;
}

.link-card p {
  margin: 0;
  font-size: 0.85rem;
  color: var(--cor-texto-suave);
  flex-grow: 1;
}

.link-card a {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--cor-marca);
  text-decoration: none;
}

.glossario-nuvem {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.termo-botao.ativo {
  background-color: #0047ab;
  border-color: #0047ab;
  color: #ffffff;
}

.termo-botao.ativo:hover,
.termo-botao.ativo:focus {
  background-color: #003580;
  border-color: #003580;
  color: #ffffff;
}

/* Glossário */
.glossario-painel {
  background: var(--cor-fundo-card);
  border-radius: 8px;
  box-shadow: var(--sombra-card);
  padding: 1.1rem 1.25rem;
  margin-bottom: 1rem;
}

.glossario-painel h6 {
  margin: 0 0 0.5rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--cor-texto-suave);
  font-size: 0.75rem;
}

