_NOME_ARQUIVO = "regionalizacao"
_LIMITE_TABELA = 2000
_COR_SEM_DESTAQUE = "#cbd2d9"
_COR_DESTAQUE = "#0047ab"


def panel_ui():
    df = dados.regionalizacao
    uos = sorted(df["uo_label"].unique())
